1	/**
2	 * Reproduce apps that are NOT managed by systemd or Docker Compose.
3	 *
4	 * The migration engine can already move a systemd service (copy the unit) and a
5	 * compose project (`docker compose up`). But plenty of real servers run their app
6	 * some other way — pm2, a hand-typed `next start` in a screen/tmux session, an
7	 * `@reboot` crontab — and those leave NO artifact the engine looks for. The site
8	 * then proxies to a port that nothing on the new box ever listens on (this is
9	 * exactly what left `/opt/nexis:3105` dark on 2026-07-27: a Next.js app with no
10	 * unit and no compose file anywhere).
11	 *
12	 * The one thing every such app DOES expose is a live listening socket. On the
13	 * source we can read, per port: the process command line and its working
14	 * directory (and, for pm2, a full structured description). That is enough to
15	 * synthesize a systemd unit on the target so the app comes up on its own and
16	 * SURVIVES A REBOOT — turning "needs a human who knows how this box was set up"
17	 * into "captured how it actually runs".
18	 *
19	 * This module is the pure parse/synthesis core (unit-tested). The SSH wiring
20	 * lives in migrate-real.ts. Everything here only ever describes a unit to CREATE;
21	 * it never removes or edits anything the customer already had.
22	 */
23	
24	/** A listening TCP socket on the source, resolved to the process behind it. */
25	export type ListeningProc = { port: number; pid: number; proc: string };
26	
27	/** A pm2-managed application, distilled to what a systemd unit needs. */
28	export type Pm2App = {
29	  name: string;
30	  cwd: string;
31	  script: string; // absolute path to the JS/entry the interpreter runs
32	  interpreter: string; // "node", "python3", … ("" ⇒ script is directly executable)
33	  args: string[]; // extra argv after the script
34	  port: number; // 0 when pm2 did not expose a PORT
35	};
36	
37	/** Ports we never synthesize a unit for — infrastructure the target provides itself. */
38	const INFRA_PORTS = new Set<number>([
39	  22, 25, 53, 80, 110, 143, 443, 465, 587, 993, 995, // ssh/mail/web/dns
40	  3306, 5432, 6379, 11211, 27017, // databases + caches
41	]);
42	
43	/** True when a listening port is worth trying to reproduce as an app service. */
44	export function capturablePort(port: number): boolean {
45	  return Number.isInteger(port) && port >= 1 && port <= 65535 && !INFRA_PORTS.has(port);
46	}
47	
48	const SAFE_PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
49	const SVC_TOKEN_RE = /^[A-Za-z0-9._-]{1,64}$/;
50	
51	/** True for an absolute path that is safe to interpolate into a shell / unit. */
52	export function safeUnitPath(p: string): boolean {
53	  return SAFE_PATH_RE.test(p);
54	}
55	
56	/**
57	 * Parse `ss -H -ltnp` output into one row per listening port.
58	 *
59	 * A line looks like:
60	 *   LISTEN 0 511 127.0.0.1:3105 0.0.0.0:* users:(("next-server",pid=1234,fd=20))
61	 *   LISTEN 0 511 *:3720 *:* users:(("node",pid=5678,fd=22))
62	 *   LISTEN 0 511 [::]:8392 [::]:* users:(("dotnet",pid=42,fd=9))
63	 *
64	 * The local address is the first field carrying a `:port`; the process is the
65	 * `users:((...))` blob. IPv6 rows keep the port after the final colon. Rows with
66	 * no `users:` (no permission to see the pid) are skipped — we cannot reproduce
67	 * what we cannot identify. First listener per port wins.
68	 */
69	export function parseSsListeners(out: string): ListeningProc[] {
70	  const byPort = new Map<number, ListeningProc>();
71	  for (const raw of String(out ?? "").split("\n")) {
72	    const line = raw.trim();
73	    if (!line) continue;
74	    const m = /users:\(\("([^"]+)",pid=(\d+),/.exec(line);
75	    if (!m) continue;
76	    const proc = m[1];
77	    const pid = Number(m[2]);
78	    // The local address is the field before "users:" that ends in :<port>.
79	    // Take the token that both contains a colon and precedes the peer address.
80	    const fields = line.split(/\s+/);
81	    let port = 0;
82	    for (const f of fields) {
83	      if (f.startsWith("users:")) break;
84	      const pm = /:(\d{1,5})$/.exec(f);
85	      if (pm) port = Number(pm[1]); // last addr:port field before users: wins
86	    }
87	    if (!capturablePort(port) || !Number.isInteger(pid) || pid <= 0) continue;
88	    if (!byPort.has(port)) byPort.set(port, { port, pid, proc });
89	  }
90	  return [...byPort.values()].sort((a, b) => a.port - b.port);
91	}
