93	/**
94	 * Parse `pm2 jlist` (its machine-readable process list) into Pm2App[].
95	 * Tolerant of missing fields and of a non-array / unparseable blob (returns []).
96	 */
97	export function parsePm2Jlist(json: string): Pm2App[] {
98	  let arr: unknown;
99	  try {
100	    arr = JSON.parse(String(json ?? ""));
101	  } catch {
102	    return [];
103	  }
104	  if (!Array.isArray(arr)) return [];
105	  const out: Pm2App[] = [];
106	  for (const raw of arr) {
107	    const p = raw as Record<string, unknown>;
108	    const env = (p?.pm2_env ?? {}) as Record<string, unknown>;
109	    const name = String(p?.name ?? "").trim();
110	    const cwd = String(env?.pm_cwd ?? "").trim();
111	    const script = String(env?.pm_exec_path ?? "").trim();
112	    // pm2 records "node"/"none"/"python3" here; "none" means the script runs itself.
113	    const interpRaw = String(env?.exec_interpreter ?? "").trim();
114	    const interpreter = interpRaw && interpRaw !== "none" ? interpRaw : "";
115	    const argv = Array.isArray(env?.args) ? (env!.args as unknown[]).map((a) => String(a)) : [];
116	    const penv = (env?.env ?? {}) as Record<string, unknown>;
117	    const port = Number(penv?.PORT ?? 0) || 0;
118	    if (!name || !safeUnitPath(cwd) || !safeUnitPath(script)) continue;
119	    out.push({ name, cwd, script, interpreter, args: argv, port });
120	  }
121	  return out;
122	}
