124	/**
125	 * The canonical `next start` command for a Next.js app, when its real argv can't
126	 * be read. Next.js overwrites its own process title, so `/proc/<pid>/cmdline`
127	 * comes back as `next-server (v16.2.10)` — not a runnable command — for exactly
128	 * the app we most want to reproduce (the /opt/nexis:3105 case). When the app dir
129	 * carries `node_modules/next/dist/bin/next`, its start command is knowable
130	 * regardless: `<node> <dir>/node_modules/next/dist/bin/next start -p <port>`.
131	 * Returns "" if any input is unsafe.
132	 */
133	export function nextStartCommand(nodePath: string, cwd: string, port: number): string {
134	  if (!safeUnitPath(nodePath) || !safeUnitPath(cwd) || !Number.isInteger(port) || port < 1 || port > 65535) return "";
135	  return `${nodePath} ${cwd}/node_modules/next/dist/bin/next start -p ${port}`;
136	}
