138	/** The trailing path component of an absolute dir, for a human-readable label. */
139	export function dirLabel(dir: string): string {
140	  const parts = String(dir ?? "").split("/").filter(Boolean);
141	  return parts.length ? parts[parts.length - 1] : "";
142	}
143	
144	/** A systemd-safe unit name derived from a label (`nxeon-app-<slug>`). */
145	export function unitNameFor(label: string): string {
146	  const slug =
147	    String(label ?? "")
148	      .toLowerCase()
149	      .replace(/[^a-z0-9]+/g, "-")
150	      .replace(/^-+|-+$/g, "")
151	      .slice(0, 40) || "app";
152	  return `nxeon-app-${slug}`;
153	}
