155	export type SynthUnitInput = {
156	  description: string;
157	  workingDir: string;
158	  /** Full ExecStart line (absolute interpreter/exec + args), already shell-safe. */
159	  execStart: string;
160	  /** PORT to inject as an Environment= line, or 0 to omit. */
161	  port?: number;
162	};
163	
164	/**
165	 * The text of a synthesized systemd unit. Deliberately conservative:
166	 * `Restart=on-failure` (not always — a crash-loop should surface, not hide),
167	 * `Type=simple`, and PORT passed through so an app that reads it from the
168	 * environment (Next.js, Rails, many Node apps) binds the same port it did before.
169	 * The unit reads the app's own `.env` from WorkingDirectory implicitly — we do
170	 * NOT copy the source process's environ, which would drag secrets and host-
171	 * specific PATH/SSH vars across; the app dir was migrated and carries its config.
172	 */
173	export function synthUnitText(input: SynthUnitInput): string {
174	  const lines = [
175	    "# Generated by the Nxeon migration engine — this app ran on the old server",
176	    "# without a systemd unit or compose file (pm2 / manual start); this unit",
177	    "# reproduces it so it comes up on boot. Safe to edit or disable.",
178	    "[Unit]",
179	    `Description=${input.description}`,
180	    "After=network-online.target",
181	    "Wants=network-online.target",
182	    "",
183	    "[Service]",
184	    "Type=simple",
185	    `WorkingDirectory=${input.workingDir}`,
186	    "EnvironmentFile=-" + input.workingDir + "/.env",
187	  ];
188	  if (input.port && Number.isInteger(input.port)) lines.push(`Environment=PORT=${input.port}`);
189	  lines.push(
190	    "Environment=NODE_ENV=production",
191	    `ExecStart=${input.execStart}`,
192	    "Restart=on-failure",
193	    "RestartSec=5",
194	    "",
195	    "[Install]",
196	    "WantedBy=multi-user.target",
197	    ""
198	  );
199	  return lines.join("\n");
200	}
201	
202	/**
203	 * Decide which of the source's listening ports actually need a synthesized unit:
204	 * a port a served vhost proxies to, that is NOT already covered by a compose
205	 * container or an enabled systemd unit on the target, and is capturable.
206	 *
207	 * `intendedPorts` — upstream ports the generated vhosts point at.
208	 * `coveredPorts`  — ports already provided by compose / an enabled unit / already
209	 *                   listening on the target.
210	 */
211	export function portsNeedingCapture(intendedPorts: Iterable<number>, coveredPorts: Iterable<number>): number[] {
212	  const covered = new Set<number>([...coveredPorts]);
213	  const out = new Set<number>();
214	  for (const p of intendedPorts) if (capturablePort(p) && !covered.has(p)) out.add(p);
215	  return [...out].sort((a, b) => a - b);
216	}
