3194	        await say(`  ${unit}: copied ${ref.path} across from the old server.`);
3195	        continue;
3196	      }
3197	    }
3198	
3199	    // 3. Refuse to guess. A unit that cannot exec is worth one loud line.
3200	    blockers.push({
3201	      domain: `${unit}.service`,
3202	      why:
3203	        `its ${ref.directive} runs ${ref.path}, which does not exist on this server and is not installed anywhere else here ` +
3204	        `(systemd fails this as 203/EXEC and restarts the service forever)`,
3205	      fix:
3206	        `install the program that provides ${base} on this server, then either symlink it — ln -s "$(command -v ${base})" ${ref.path} — ` +
3207	        `or edit ${unitFile} to the real path, and run: systemctl daemon-reload && systemctl restart ${unit}`,
3208	    });
3209	  }
3210	  return { ok: blockers.length === 0, repairs, blockers };
