3216	/**
3217	 * The two questions the `/home` expansion has to ask, as an interface rather
3218	 * than a `Client` — because the whole defect this seam exists to prevent was
3219	 * asking the WRONG MACHINE.
3220	 *
3221	 * Incident (found by the 2026-07-27 line audit): `/home` is in `UNSAFE_EXACT`
3222	 * (copying it wholesale would overwrite the new server's own accounts) AND in
3223	 * `DEFAULT_PATHS` (`lib/actions-migrate.ts`), so it is in the default selection
3224	 * of every migration. The fix for that — expand `/home` into its per-user
3225	 * subdirectories — enumerated `/home` with `sh(conn, "ls -1 /home")`, and `conn`
3226	 * is the TARGET connection. A freshly-provisioned Nxeon VPS has an empty (or
3227	 * single-account) `/home`, so the list came back empty and the run pushed:
3228	 *
3229	 *     Copy /home — skipped — "the old server has no user home directories under /home"
3230	 *
3231	 * A statement about the OLD server, produced by looking at the NEW one. Every
3232	 * home directory on the source was silently left behind, and on the HestiaCP /
3233	 * cPanel layout the field notes describe (`/home/<user>/public_html`) that is
3234	 * the customer's entire web estate. The previous version of this bug dropped
3235	 * `/home` with a silent `.filter()`; this version dropped it with a sentence
3236	 * that was not true.
3237	 *
3238	 * Naming the two sides in the type is the point: `listSourceHomes` cannot be
3239	 * implemented against the target without the name reading as a lie.
3240	 */
3241	/**
3242	 * The command that enumerates `/home` ON THE SOURCE, built through the caller's
3243	 * `onSource` wrapper.
3244	 *
3245	 * A one-line function with a test behind it, because "which machine did we ask?"
3246	 * has no other mechanical witness. The bug it pins was a single missing wrapper —
3247	 * `sh(conn, "ls -1 /home")` instead of `sh(conn, onSource("ls -1 /home"))` — and
3248	 * both spellings compile, lint, typecheck and run. `test/migration-gate.test.ts`
3249	 * asserts the result actually travels through `onSource`, so re-introducing the
3250	 * target-side read turns a test red instead of turning a customer's home
3251	 * directories into a sentence about the old server that is not true.
3252	 */
3253	export function sourceHomeListCommand(onSource: (cmd: string) => string): string {
3254	  return `${onSource("ls -1 /home 2>/dev/null | head -n 60")} 2>/dev/null`;
3255	}
