2580	export function parseListeningPorts(stdout: string): Set<number> {
2581	  const ports = new Set<number>();
2582	  for (const l of cleanRows(stdout, 12000)) {
2583	    const m = /:(\d{1,5})$/.exec(l);
2584	    if (!m) continue; // the `Local Address:Port` header row, and IPv6 without a port
2585	    const p = Number(m[1]);
2586	    if (Number.isInteger(p) && p >= 1 && p <= 65535) ports.add(p);
2587	  }
2588	  return ports;
2589	}
