2591	/**
2592	 * The variables a compose file REQUIRES from its environment: `${VAR}` with no
2593	 * default. `${VAR:-fallback}` and `${VAR-fallback}` supply their own value and
2594	 * are deliberately excluded.
2595	 *
2596	 * Incident (2026-07-26 rehearsal): built from `clean(stdout).split("\n")` over
2597	 * `grep -o '\$\{...\}'` output, which is one token per line. Glued, the whole
2598	 * list became `${DB_PASSWORD}${REDIS_URL}${API_KEY}` and the `^`-anchored regex
2599	 * returned only the first name. Field note 12 exists to REFUSE to start a stack
2600	 * whose secrets did not come across and to name the missing variables; with one
2601	 * name out of N it named the wrong thing and passed the rest.
2602	 */
2603	export function parseComposeRequiredVars(stdout: string): string[] {
2604	  const required = new Set<string>();
2605	  for (const tok of cleanRows(stdout, 6000)) {
2606	    const m = /^\$\{([A-Za-z_][A-Za-z0-9_]*)(:?[-?+])?/.exec(tok);
2607	    if (!m || m[2]) continue; // `${VAR:-default}` supplies its own value
2608	    required.add(m[1]);
2609	  }
